  builder_.add_FALSE_ALARM_PROBABILITY_REQUIREMENT(FALSE_ALARM_PROBABILITY_REQUIREMENT);
  builder_.add_TARGET_RCS_M2(TARGET_RCS_M2);
  builder_.add_CFAR_LOSS_DB(CFAR_LOSS_DB);
  builder_.add_CANONICAL_JSON_SIGNATURE(CANONICAL_JSON_SIGNATURE);
  builder_.add_SIGNATURE(SIGNATURE);
  builder_.add_PRODUCER_ID(PRODUCER_ID);
  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_SNR_DB(SNR_DB);
  builder_.add_FALSE_ALARM_PROBABILITY(FALSE_ALARM_PROBABILITY);
  builder_.add_DETECTION_PROBABILITY(DETECTION_PROBABILITY);
  builder_.add_RANGE_M(RANGE_M);
  builder_.add_CFAR_GUARD_CELL_COUNT(CFAR_GUARD_CELL_COUNT);
  builder_.add_CFAR_REFERENCE_CELL_COUNT(CFAR_REFERENCE_CELL_COUNT);
  builder_.add_PULSE_COUNT(PULSE_COUNT);
