  auto _RSD_ID = _fbb.CreateString(_o->RSD_ID);
  auto _NAME = _o->NAME.empty() ? 0 : _fbb.CreateString(_o->NAME);
  auto _SCENARIO_ID = _o->SCENARIO_ID.empty() ? 0 : _fbb.CreateString(_o->SCENARIO_ID);
  auto _SENSOR_ID = _o->SENSOR_ID.empty() ? 0 : _fbb.CreateString(_o->SENSOR_ID);
  auto _SNR_ID = _o->SNR_ID.empty() ? 0 : _fbb.CreateString(_o->SNR_ID);
