  auto _APL_ID = _o->APL_ID.empty() ? 0 : _fbb.CreateString(_o->APL_ID);
  auto _WAVEFORM = _o->WAVEFORM;
  auto _INTEGRATION = _o->INTEGRATION;
  auto _CFAR = _o->CFAR;
  auto _TARGET_MODEL = _o->TARGET_MODEL;
  auto _PULSE_COUNT = _o->PULSE_COUNT;
  auto _CFAR_REFERENCE_CELL_COUNT = _o->CFAR_REFERENCE_CELL_COUNT;
  auto _CFAR_GUARD_CELL_COUNT = _o->CFAR_GUARD_CELL_COUNT;
  auto _CFAR_LOSS_DB = _o->CFAR_LOSS_DB;
  auto _TARGET_RCS_M2 = _o->TARGET_RCS_M2;
  auto _FALSE_ALARM_PROBABILITY_REQUIREMENT = _o->FALSE_ALARM_PROBABILITY_REQUIREMENT;
  auto _DETECTION_PROBABILITY_REQUIREMENT = _o->DETECTION_PROBABILITY_REQUIREMENT;
  auto _RANGE_M = _fbb.CreateVector(_o->RANGE_M);
  auto _DETECTION_PROBABILITY = _fbb.CreateVector(_o->DETECTION_PROBABILITY);
  auto _FALSE_ALARM_PROBABILITY = _fbb.CreateVector(_o->FALSE_ALARM_PROBABILITY);
  auto _SNR_DB = _fbb.CreateVector(_o->SNR_DB);
  auto _MAXIMUM_DETECTION_RANGE_M = _o->MAXIMUM_DETECTION_RANGE_M;
  auto _MINIMUM_DETECTABLE_RCS_M2 = _o->MINIMUM_DETECTABLE_RCS_M2;
  auto _RANGE_AT_PD_0P5_M = _o->RANGE_AT_PD_0P5_M;
  auto _RANGE_AT_PD_0P9_M = _o->RANGE_AT_PD_0P9_M;
  auto _CLUTTER_TO_NOISE_DB = _o->CLUTTER_TO_NOISE_DB;
  auto _PROPAGATION_LOSS_DB = _o->PROPAGATION_LOSS_DB;
  auto _JAMMING_TO_SIGNAL_DB = _o->JAMMING_TO_SIGNAL_DB;
