inline const RSD *GetRSD(const void *buf) {
  return ::flatbuffers::GetRoot<RSD>(buf);
}

inline const RSD *GetSizePrefixedRSD(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<RSD>(buf);
}

inline const char *RSDIdentifier() {
  return "$RSD";
}

inline bool RSDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RSDIdentifier());
}

inline bool SizePrefixedRSDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RSDIdentifier(), true);
}

template <bool B = false>
inline bool VerifyRSDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<RSD>(RSDIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedRSDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<RSD>(RSDIdentifier());
}

inline void FinishRSDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RSD> root) {
  fbb.Finish(root, RSDIdentifier());
}

inline void FinishSizePrefixedRSDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RSD> root) {
  fbb.FinishSizePrefixed(root, RSDIdentifier());
}

inline std::unique_ptr<RSDT> UnPackRSD(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RSDT>(GetRSD(buf)->UnPack(res));
}

inline std::unique_ptr<RSDT> UnPackSizePrefixedRSD(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RSDT>(GetSizePrefixedRSD(buf)->UnPack(res));
}

